import{_ as a,o as s,c as n,S as o}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse('{"title":"Mac M1系统配置C++环境","description":"最近在学习计算机图形学，需要配置C++环境和opencv来编译作业代码，于是我就开始折腾下M1如何编译C++代码了。","frontmatter":{"title":"Mac M1系统配置C++环境","date":"2022-04-13 20:03","comments":true,"archives":2022,"tags":["C++"]},"headers":[],"relativePath":"posts/2022-04-13-m1-cpp/index.md","filePath":"posts/2022/2022-04-13-m1-cpp.md"}'),l={name:"posts/2022-04-13-m1-cpp/index.md"};function r(p,e,t,c,i,d){return s(),n("div",null,[...e[0]||(e[0]=[o(`<p>最近在学习计算机图形学，需要配置C++环境和opencv来编译作业代码，于是我就开始折腾下M1如何编译C++代码了。</p><h2 id="安装依赖" tabindex="-1">安装依赖 <a class="header-anchor" href="#安装依赖" aria-label="Permalink to &quot;安装依赖&quot;">​</a></h2><p>首先你需要安装Mac下的包管理器 <a href="https://brew.sh/" target="_blank" rel="noreferrer">homebrew</a>，官网有详细的安装教程，我就不赘述了。</p><p>接下来安装C++相关的依赖：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">brew</span><span style="color:#032F62;"> install</span><span style="color:#032F62;"> gcc</span><span style="color:#032F62;"> cmake</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>然后是图形学相关的依赖：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">brew</span><span style="color:#032F62;"> install</span><span style="color:#032F62;"> eigen</span><span style="color:#032F62;"> opencv</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="配置头文件路径" tabindex="-1">配置头文件路径 <a class="header-anchor" href="#配置头文件路径" aria-label="Permalink to &quot;配置头文件路径&quot;">​</a></h2><blockquote><p>This script installs Homebrew to its preferred prefix (/usr/local for macOS Intel, /opt/homebrew for Apple Silicon and /home/linuxbrew/.linuxbrew for Linux) so that you don’t need sudo when you brew install.</p></blockquote><p>homebrew 官网有描述M1的安装路径更改到 <code>/opt/homebrew</code> 了。所以我们需要指定头文件路径，这里我们指定到 <code>/opt/homebrew/include</code>。</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">export</span><span style="color:#24292E;"> CPATH</span><span style="color:#D73A49;">=</span><span style="color:#24292E;">/opt/homebrew/include</span></span>
<span class="line"><span style="color:#D73A49;">export</span><span style="color:#24292E;"> LIBRARY_PATH</span><span style="color:#D73A49;">=</span><span style="color:#24292E;">/opt/homebrew/lib</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>把上述代码添加到 <code>.bashrc</code> 文件，如果你使用的是 zsh 请添加到 <code>.zshrc</code> 文件。</p><h2 id="检测头文件路径" tabindex="-1">检测头文件路径 <a class="header-anchor" href="#检测头文件路径" aria-label="Permalink to &quot;检测头文件路径&quot;">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">gcc</span><span style="color:#005CC5;"> -x</span><span style="color:#032F62;"> c++</span><span style="color:#005CC5;"> -v</span><span style="color:#005CC5;"> -E</span><span style="color:#032F62;"> /dev/null</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>如果输出结果有 <code>/opt/homebrew/include</code> 就说明配置成功了。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>配置环境看似简单，但找到解决方案需要花不少时间，这里主要问题是M1下安装路径不同，所以我们需要指定头文件路径。</p><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><p><a href="https://apple.stackexchange.com/questions/414622/installing-a-c-c-library-with-homebrew-on-m1-macs" target="_blank" rel="noreferrer">Installing a C/C++ library with homebrew on M1 Macs</a></p><p><a href="https://zhuanlan.zhihu.com/p/371245964" target="_blank" rel="noreferrer">在 Mac OS 下配置 GAMES101 开发环境</a></p><p><a href="https://stackoverflow.com/questions/19852199/view-default-include-path-of-c-headers-in-mac-os-x-by-gcc-v" target="_blank" rel="noreferrer">View default include path of C headers in Mac OS X by gcc -v?</a></p>`,21)])])}const u=a(l,[["render",r]]);export{b as __pageData,u as default};
